package com.envarg.qrhisab;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.os.*;import android.text.*;import android.webkit.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 WebView web; ValueCallback<Uri[]> chooser;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.rgb(68,57,173));getWindow().setNavigationBarColor(Color.rgb(243,244,251));web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){String url=r.getUrl().toString();if(url.startsWith("file:///android_asset/"))return false;open(url);return true;}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;try{startActivityForResult(p.createIntent(),41);}catch(Exception e){chooser=null;cb.onReceiveValue(null);}return true;}});web.loadUrl("file:///android_asset/index.html");}
 @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==41&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));chooser=null;}}
 void open(String url){try{Uri u=Uri.parse(url);if(!java.util.Arrays.asList("https","mailto","tel").contains(u.getScheme()))return;startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){message("इसे खोलने वाली ऐप नहीं मिली");}}
 void message(String s){runOnUiThread(()->android.widget.Toast.makeText(this,s,android.widget.Toast.LENGTH_LONG).show());}
 Uri save(String name,byte[] bytes)throws IOException{File dir=new File(getCacheDir(),"shared");dir.mkdirs();String safe=name.replaceAll("[^a-zA-Z0-9._-]","_");if(safe.length()>100)safe=safe.substring(safe.length()-100);File f=new File(dir,safe);try(FileOutputStream out=new FileOutputStream(f)){out.write(bytes);}return new Uri.Builder().scheme("content").authority(getPackageName()+".files").appendPath(safe).build();}
 void send(Uri uri,String mime,String email,String subject,String text){Intent i=new Intent(Intent.ACTION_SEND);i.setType(mime);i.putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri("statement",uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.putExtra(Intent.EXTRA_SUBJECT,subject);i.putExtra(Intent.EXTRA_TEXT,text);if(!email.isEmpty())i.putExtra(Intent.EXTRA_EMAIL,new String[]{email});try{startActivity(Intent.createChooser(i,email.isEmpty()?"शेयर / सेव करें":"Gmail / ईमेल चुनें, फिर Send दबाएँ"));}catch(Exception e){message("शेयर करने वाली ऐप नहीं मिली");}}
 byte[] pdf(String text)throws IOException{PdfDocument doc=new PdfDocument();TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.rgb(32,35,59));paint.setTextSize(12);StaticLayout layout=StaticLayout.Builder.obtain(text,0,text.length(),paint,515).setAlignment(Layout.Alignment.ALIGN_NORMAL).setLineSpacing(3,1).build();int height=750,pages=(layout.getHeight()+height-1)/height;for(int n=0;n<pages;n++){PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,n+1).create());Canvas c=page.getCanvas();c.save();c.clipRect(40,40,555,790);c.translate(40,40-n*height);layout.draw(c);c.restore();doc.finishPage(page);}ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);doc.close();return out.toByteArray();}
 class Bridge{
 @JavascriptInterface public boolean canBiometric(){if(Build.VERSION.SDK_INT<29)return false;android.hardware.biometrics.BiometricManager b=getSystemService(android.hardware.biometrics.BiometricManager.class);return b!=null&&b.canAuthenticate()==android.hardware.biometrics.BiometricManager.BIOMETRIC_SUCCESS;}
 @JavascriptInterface public void unlockBiometric(){if(!canBiometric())return;runOnUiThread(()->new android.hardware.biometrics.BiometricPrompt.Builder(MainActivity.this).setTitle("Envarg QR हिसाब खोलें").setNegativeButton("रद्द",getMainExecutor(),(d,w)->{}).build().authenticate(new CancellationSignal(),getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult r){web.evaluateJavascript("locked=false;failures=0;render();",null);}}));}

 @JavascriptInterface public void openExternal(String url){runOnUiThread(()->open(url));}
 @JavascriptInterface public void shareFile(String name,String data,String mime,String email,String subject,String text){runOnUiThread(()->{try{if(name.equals("statement.txt")){send(save("Envarg-statement.pdf",pdf(data)),"application/pdf",email,subject,"पूरा स्टेटमेंट PDF संलग्न है।");return;}byte[] bytes=data.startsWith("data:")?android.util.Base64.decode(data.substring(data.indexOf(',')+1),android.util.Base64.DEFAULT):data.getBytes(StandardCharsets.UTF_8);send(save(name,bytes),mime,email,subject,text);}catch(Exception e){message("फाइल शेयर नहीं हुई: "+e.getMessage());}});}
 @JavascriptInterface public void printStatement(String text){runOnUiThread(()->{try{send(save("Envarg-statement.pdf",pdf(text)),"application/pdf","","Envarg स्टेटमेंट","");}catch(Exception e){message("PDF नहीं बनी: "+e.getMessage());}});}
 }
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setMessage("ऐप बंद करें?").setPositiveButton("हाँ",(d,w)->finish()).setNegativeButton("नहीं",null).show();}
}
